package com.bingoteamicons;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Reads and writes the roster config keys, and owns the saved preset blob.
 *
 * <p>Keeping this out of the panel means the merge logic is plain data in, plain
 * data out, so it can be reasoned about without a Swing component in scope.
 */
@Singleton
@Slf4j
class BingoTeamIconsRosterStore
{
	static final String PRESETS_KEY = "presets";

	private static final int MAX_PRESETS = 20;
	private static final int MAX_PRESETS_JSON_CHARS = 64 * 1024;

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	BingoTeamIconsRosterStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	static class PresetLimitException extends Exception
	{
		PresetLimitException(String message)
		{
			super(message);
		}
	}

	/** Outcome of merging an incoming roster into the configured one, computed before anything is written. */
	static class MergePlan
	{
		BingoTeamIconsSyncCodec.SyncPayload result;
		final List<String> overflowLabels = new ArrayList<>();
		int updatedTeams;
		int addedTeams;
		int addedPlayers;

		boolean fits()
		{
			return overflowLabels.isEmpty();
		}
	}

	int teamCount()
	{
		String stored = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsConfig.TEAM_COUNT_KEY);
		if (stored != null)
		{
			try
			{
				return clampTeamCount(Integer.parseInt(stored));
			}
			catch (NumberFormatException ex)
			{
				log.debug("invalid stored team count: {}", stored);
			}
		}
		return 2;
	}

	static int clampTeamCount(int count)
	{
		return Math.min(Math.max(count, 1), BingoTeamIconsPlugin.MAX_TEAMS);
	}

	/** Never null; empty when the user has not named the team. */
	String teamLabel(int team)
	{
		String stored = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamLabelKey(team));
		return stored == null ? "" : BingoTeamIconsSyncCodec.sanitizeLabel(stored);
	}

	String teamNames(int team)
	{
		String stored = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamNamesKey(team));
		return stored == null ? "" : stored;
	}

	private String teamColorHex(int team)
	{
		String stored = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamColorKey(team));
		return stored == null || stored.isEmpty() ? null : stored;
	}

	/** The configured roster, slots 1..teamCount. */
	BingoTeamIconsSyncCodec.SyncPayload read(String label)
	{
		BingoTeamIconsSyncCodec.SyncPayload payload = new BingoTeamIconsSyncCodec.SyncPayload();
		payload.label = BingoTeamIconsSyncCodec.sanitizeLabel(label);
		payload.teams = new ArrayList<>();

		int count = teamCount();
		for (int team = 1; team <= count; team++)
		{
			BingoTeamIconsSyncCodec.SyncTeam syncTeam = new BingoTeamIconsSyncCodec.SyncTeam();
			syncTeam.name = teamLabel(team);
			syncTeam.color = teamColorHex(team);
			syncTeam.members = BingoTeamIconsSyncCodec.encodeMembers(splitNames(teamNames(team)));
			payload.teams.add(syncTeam);
		}
		return payload;
	}

	/**
	 * Writes a roster into slots 1..n. Slots past n are left alone rather than
	 * cleared, matching what lowering the team count already does — they are
	 * inert because every reader stops at teamCount.
	 *
	 * <p>Callers must wrap this in {@link BingoTeamIconsPlugin#applyBulkConfigChange}
	 * so the ~30 writes propagate once instead of once each.
	 */
	void write(BingoTeamIconsSyncCodec.SyncPayload payload)
	{
		int count = clampTeamCount(payload.teams.size());
		for (int team = 1; team <= count; team++)
		{
			BingoTeamIconsSyncCodec.SyncTeam syncTeam = payload.teams.get(team - 1);

			configManager.setConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamLabelKey(team),
				syncTeam.name == null ? "" : syncTeam.name);
			configManager.setConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamNamesKey(team),
				String.join(", ", syncTeam.memberList()));

			if (syncTeam.color != null && !syncTeam.color.isEmpty())
			{
				configManager.setConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamColorKey(team),
					syncTeam.color);
			}
		}

		configManager.setConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsConfig.TEAM_COUNT_KEY, count);
	}

	static List<String> splitNames(String blob)
	{
		List<String> names = new ArrayList<>();
		if (blob == null || blob.isEmpty())
		{
			return names;
		}

		for (String name : blob.split("[,\n]"))
		{
			String trimmed = name.trim();
			if (!trimmed.isEmpty())
			{
				names.add(trimmed);
			}
		}
		return names;
	}

	/**
	 * Works out where each incoming team would land if merged into the existing
	 * roster. Teams are matched by name; a team with no name matches nothing,
	 * since silently merging two unnamed teams would be unrecoverable.
	 */
	static MergePlan planMerge(BingoTeamIconsSyncCodec.SyncPayload existing, BingoTeamIconsSyncCodec.SyncPayload incoming)
	{
		MergePlan plan = new MergePlan();
		plan.result = new BingoTeamIconsSyncCodec.SyncPayload();
		plan.result.label = incoming.label;
		plan.result.teams = new ArrayList<>(existing.teams);

		for (BingoTeamIconsSyncCodec.SyncTeam incomingTeam : incoming.teams)
		{
			int slot = indexOfLabel(plan.result.teams, incomingTeam.name);
			if (slot >= 0)
			{
				BingoTeamIconsSyncCodec.SyncTeam local = plan.result.teams.get(slot);

				// merge is additive: the local team keeps its own name and colour,
				// so a merge can never repaint teams the user already set up
				LinkedHashSet<String> union = new LinkedHashSet<>(local.memberList());
				int before = union.size();
				union.addAll(incomingTeam.memberList());
				plan.addedPlayers += union.size() - before;

				BingoTeamIconsSyncCodec.SyncTeam merged = new BingoTeamIconsSyncCodec.SyncTeam();
				merged.name = local.name;
				merged.color = local.color;
				merged.members = BingoTeamIconsSyncCodec.encodeMembers(union);
				plan.result.teams.set(slot, merged);
				plan.updatedTeams++;
				continue;
			}

			int free = indexOfUnused(plan.result.teams);
			if (free >= 0)
			{
				plan.result.teams.set(free, incomingTeam);
			}
			else if (plan.result.teams.size() < BingoTeamIconsPlugin.MAX_TEAMS)
			{
				plan.result.teams.add(incomingTeam);
			}
			else
			{
				String name = normalizeLabel(incomingTeam.name).isEmpty()
					? "(unnamed team)"
					: incomingTeam.name.trim();
				plan.overflowLabels.add(name);
				continue;
			}

			plan.addedTeams++;
			plan.addedPlayers += incomingTeam.memberList().size();
		}

		return plan;
	}

	private static int indexOfLabel(List<BingoTeamIconsSyncCodec.SyncTeam> teams, String label)
	{
		String needle = normalizeLabel(label);
		if (needle.isEmpty())
		{
			return -1;
		}

		for (int i = 0; i < teams.size(); i++)
		{
			if (normalizeLabel(teams.get(i).name).equals(needle))
			{
				return i;
			}
		}
		return -1;
	}

	/** A slot the user demonstrably never set up: no name and no members. */
	private static int indexOfUnused(List<BingoTeamIconsSyncCodec.SyncTeam> teams)
	{
		for (int i = 0; i < teams.size(); i++)
		{
			BingoTeamIconsSyncCodec.SyncTeam team = teams.get(i);
			if (normalizeLabel(team.name).isEmpty() && team.memberList().isEmpty())
			{
				return i;
			}
		}
		return -1;
	}

	private static String normalizeLabel(String label)
	{
		return label == null ? "" : label.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
	}

	static String displayName(BingoTeamIconsSyncCodec.SyncTeam team, int slot)
	{
		String name = team == null ? null : team.name;
		return name == null || name.trim().isEmpty() ? "Team " + slot : name.trim();
	}

	LinkedHashMap<String, String> readPresets()
	{
		LinkedHashMap<String, String> presets = new LinkedHashMap<>();
		String json = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, PRESETS_KEY);
		if (json == null || json.isEmpty())
		{
			return presets;
		}

		try
		{
			JsonObject object = gson.fromJson(json, JsonObject.class);
			if (object == null)
			{
				return presets;
			}

			for (Map.Entry<String, JsonElement> entry : object.entrySet())
			{
				JsonElement value = entry.getValue();
				if (value != null && value.isJsonPrimitive())
				{
					presets.put(entry.getKey(), value.getAsString());
				}
			}
		}
		catch (JsonParseException ex)
		{
			// a corrupt blob must not brick the panel; the user can just re-save
			log.debug("discarding unreadable presets value", ex);
		}
		return presets;
	}

	void savePreset(String label, String code) throws PresetLimitException
	{
		String clean = BingoTeamIconsSyncCodec.sanitizeLabel(label);
		if (clean.isEmpty())
		{
			throw new PresetLimitException("Give the preset a name first.");
		}

		LinkedHashMap<String, String> presets = readPresets();
		if (!presets.containsKey(clean) && presets.size() >= MAX_PRESETS)
		{
			throw new PresetLimitException("You already have " + MAX_PRESETS
				+ " saved presets. Delete one before saving another.");
		}

		presets.put(clean, code);

		String json = gson.toJson(presets);
		if (json.length() > MAX_PRESETS_JSON_CHARS)
		{
			throw new PresetLimitException("These rosters are too large to save as a preset. "
				+ "Share them as a file instead.");
		}

		configManager.setConfiguration(BingoTeamIconsConfig.GROUP, PRESETS_KEY, json);
	}

	void deletePreset(String label)
	{
		LinkedHashMap<String, String> presets = readPresets();
		if (presets.remove(label) != null)
		{
			configManager.setConfiguration(BingoTeamIconsConfig.GROUP, PRESETS_KEY, gson.toJson(presets));
		}
	}
}

package com.bingoteamicons;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Generates the colored badge images used as chat icons, plus the sidebar
 * navigation icon. Badges are 11x11 to match the game's rank icon dimensions
 * so they align with other chat icons.
 */
final class TeamIconFactory
{
	private static final Color[] DEFAULT_TEAM_COLORS = {
		new Color(0xE6194B), // red
		new Color(0x4363D8), // blue
		new Color(0x3CB44B), // green
		new Color(0xFFE119), // yellow
		new Color(0x911EB4), // purple
		new Color(0xF58231), // orange
		new Color(0x42D4F4), // cyan
		new Color(0xF032E6), // magenta
		new Color(0x9A6324), // brown
		new Color(0xA9A9A9), // gray
	};

	// matches ChatIconManager.IMAGE_DIMENSION used for rank icons
	static final int BADGE_SIZE = 11;
	private static final Color OUTLINE_COLOR = new Color(33, 33, 33);

	private TeamIconFactory()
	{
	}

	static Color defaultTeamColor(int teamNumber)
	{
		return DEFAULT_TEAM_COLORS[(teamNumber - 1) % DEFAULT_TEAM_COLORS.length];
	}

	static BufferedImage createBadge(Color color)
	{
		BufferedImage image = new BufferedImage(BADGE_SIZE, BADGE_SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();

		g.setColor(color);
		g.fillOval(0, 1, BADGE_SIZE - 2, BADGE_SIZE - 2);
		g.setColor(OUTLINE_COLOR);
		g.drawOval(0, 1, BADGE_SIZE - 2, BADGE_SIZE - 2);

		g.dispose();
		return image;
	}

	static BufferedImage createPanelIcon()
	{
		final int size = 16;
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		// 2x2 bingo-card grid using the first four default team colors
		int cell = 7;
		g.setColor(defaultTeamColor(1));
		g.fillRect(0, 0, cell, cell);
		g.setColor(defaultTeamColor(2));
		g.fillRect(cell + 2, 0, cell, cell);
		g.setColor(defaultTeamColor(3));
		g.fillRect(0, cell + 2, cell, cell);
		g.setColor(defaultTeamColor(4));
		g.fillRect(cell + 2, cell + 2, cell, cell);

		g.dispose();
		return image;
	}
}

package com.bingoteamicons;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.io.BufferedReader;
import java.io.IOException;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import net.runelite.client.util.Filepath;

/**
 * The import and export dialogs. Kept out of the panel so the roster editor
 * stays readable; this is all Swing plumbing and file handling.
 */
final class BingoTeamIconsSyncDialogs
{
	/** Codes longer than this will not fit in a single Discord message. */
	private static final int DISCORD_MESSAGE_LIMIT = 1900;
	private static final int MAX_FILE_CHARS = 1024 * 1024;
	private static final String EXTENSION = "bti";

	enum Choice
	{
		REPLACE,
		MERGE
	}

	private BingoTeamIconsSyncDialogs()
	{
	}

	static void showExport(Component parent, String code)
	{
		JTextArea codeArea = new JTextArea(code, 8, 40);
		codeArea.setEditable(false);
		codeArea.setLineWrap(true);
		codeArea.setWrapStyleWord(false);
		codeArea.setCaretPosition(0);

		JPanel content = new JPanel(new BorderLayout(0, 6));
		content.add(new JLabel("Share this code. Anyone with it can import your teams."), BorderLayout.NORTH);
		content.add(new JScrollPane(codeArea), BorderLayout.CENTER);

		String note = code.length() + " characters."
			+ (code.length() > DISCORD_MESSAGE_LIMIT
			? " That is too long for one Discord message, so save it to a file and attach that instead."
			: "");
		JLabel noteLabel = new JLabel("<html><body style='width:380px'>" + note + "</body></html>");
		content.add(noteLabel, BorderLayout.SOUTH);

		JButton copy = new JButton("Copy to clipboard");
		copy.addActionListener(e -> Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(code), null));

		JButton save = new JButton("Save to file...");
		save.addActionListener(e -> saveToFile(parent, code));

		JOptionPane.showOptionDialog(parent, content, "Export teams",
			JOptionPane.DEFAULT_OPTION, JOptionPane.PLAIN_MESSAGE, null,
			new Object[]{copy, save, "Close"}, copy);
	}

	/** Returns the raw pasted or loaded code, or null if the user cancelled. */
	static String promptForCode(Component parent)
	{
		JTextArea input = new JTextArea(8, 40);
		input.setLineWrap(true);
		input.setWrapStyleWord(false);

		JPanel content = new JPanel(new BorderLayout(0, 6));
		content.add(new JLabel("Paste a team code, or load one from a file."), BorderLayout.NORTH);
		content.add(new JScrollPane(input), BorderLayout.CENTER);

		JButton load = new JButton("Load from file...");
		load.addActionListener(e ->
		{
			String loaded = loadFromFile(parent);
			if (loaded != null)
			{
				input.setText(loaded);
			}
		});

		JPanel south = new JPanel(new BorderLayout());
		south.add(load, BorderLayout.WEST);
		content.add(south, BorderLayout.SOUTH);

		int result = JOptionPane.showConfirmDialog(parent, content, "Import teams",
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

		if (result != JOptionPane.OK_OPTION)
		{
			return null;
		}
		return input.getText();
	}

	/**
	 * Shows what the import would do and asks how to apply it. Returns null if the
	 * user cancelled. Merge is not offered when it would not fit, since silently
	 * dropping a team from a bingo roster is the worst available outcome.
	 */
	static Choice confirmImport(Component parent, BingoTeamIconsSyncCodec.SyncPayload incoming,
		BingoTeamIconsRosterStore.MergePlan plan)
	{
		StringBuilder summary = new StringBuilder();
		if (!incoming.label.isEmpty())
		{
			summary.append(incoming.label).append("\n\n");
		}

		int total = 0;
		for (int i = 0; i < incoming.teams.size(); i++)
		{
			BingoTeamIconsSyncCodec.SyncTeam team = incoming.teams.get(i);
			int size = team.memberList().size();
			total += size;
			summary.append("  ")
				.append(BingoTeamIconsRosterStore.displayName(team, i + 1))
				.append(" - ")
				.append(size)
				.append(size == 1 ? " player" : " players")
				.append('\n');
		}
		summary.append('\n').append(incoming.teams.size()).append(" teams, ").append(total).append(" players.\n");

		if (plan.fits())
		{
			summary.append("\nMerging would update ").append(plan.updatedTeams)
				.append(" existing team(s), add ").append(plan.addedTeams)
				.append(" new team(s) and ").append(plan.addedPlayers).append(" new player(s).");
		}
		else
		{
			summary.append("\nThese teams will not fit alongside your existing ones (")
				.append(BingoTeamIconsPlugin.MAX_TEAMS).append(" teams maximum):\n  ")
				.append(String.join(", ", plan.overflowLabels))
				.append("\n\nYou can still replace your teams with this code.");
		}

		JTextArea summaryArea = new JTextArea(summary.toString());
		summaryArea.setEditable(false);
		summaryArea.setOpaque(false);
		summaryArea.setBorder(BorderFactory.createEmptyBorder());

		JScrollPane scroll = new JScrollPane(summaryArea);
		scroll.setPreferredSize(new Dimension(360, 240));
		scroll.setBorder(BorderFactory.createEmptyBorder());

		Object[] options = plan.fits()
			? new Object[]{"Merge", "Replace all", "Cancel"}
			: new Object[]{"Replace all", "Cancel"};

		int choice = JOptionPane.showOptionDialog(parent, scroll, "Import teams",
			JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0]);

		if (choice < 0)
		{
			return null;
		}

		String picked = (String) options[choice];
		if ("Merge".equals(picked))
		{
			return Choice.MERGE;
		}
		if ("Replace all".equals(picked))
		{
			return Choice.REPLACE;
		}
		return null;
	}

	static String promptForPresetName(Component parent, String initial)
	{
		Object result = JOptionPane.showInputDialog(parent, "Name this set of teams:", "Save preset",
			JOptionPane.PLAIN_MESSAGE, null, null, initial == null ? "" : initial);
		return result == null ? null : result.toString();
	}

	static boolean confirm(Component parent, String title, String message)
	{
		return JOptionPane.showConfirmDialog(parent, message, title,
			JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.OK_OPTION;
	}

	static void showError(Component parent, String message)
	{
		JOptionPane.showMessageDialog(parent, message, "Bingo Team Icons", JOptionPane.ERROR_MESSAGE);
	}

	private static void saveToFile(Component parent, String code)
	{
		List<Filepath> picked = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save team code")
			.setFileName("bingo-teams." + EXTENSION)
			.addExtensionFilter("Bingo team code (*." + EXTENSION + ")", EXTENSION)
			.setDefaultExtension(EXTENSION)
			.showDialog(parent);

		if (picked.isEmpty())
		{
			return;
		}

		Filepath file = picked.get(0);
		if (file.exists() && !confirm(parent, "Overwrite file",
			file.getFileName() + " already exists. Overwrite it?"))
		{
			return;
		}

		try
		{
			file.write(code);
		}
		catch (IOException ex)
		{
			showError(parent, "Could not save the file: " + ex.getMessage());
		}
	}

	private static String loadFromFile(Component parent)
	{
		List<Filepath> picked = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setDialogTitle("Load team code")
			.addExtensionFilter("Bingo team code (*." + EXTENSION + ")", EXTENSION)
			.showDialog(parent);

		if (picked.isEmpty())
		{
			return null;
		}

		Filepath file = picked.get(0);
		StringBuilder text = new StringBuilder();
		try
		{
			if (file.size() > MAX_FILE_CHARS)
			{
				showError(parent, "That file is too large to be a team code.");
				return null;
			}

			try (BufferedReader reader = file.openBufferedReader())
			{
				char[] buffer = new char[8192];
				int read;
				while ((read = reader.read(buffer)) > 0 && text.length() <= MAX_FILE_CHARS)
				{
					text.append(buffer, 0, read);
				}
			}
		}
		catch (IOException ex)
		{
			showError(parent, "Could not read the file: " + ex.getMessage());
			return null;
		}

		return text.toString();
	}
}

