	private void refreshPanelOnlineCounts()
	{
		BingoTeamIconsPanel p = panel;
		if (p != null)
		{
			p.refreshOnlineCounts();
		}
	}

	/**
	 * Counts rostered players per team who are currently online in the clan
	 * channel, guest clan channel, or friends chat channel. Reads client state
	 * on the client thread and delivers the result on the Swing EDT.
	 */
	void computeOnlineCounts(Consumer<Map<Integer, Integer>> consumer)
	{
		clientThread.invokeLater(() ->
		{
			Set<String> onlineNames = new HashSet<>();

			ClanChannel clan = client.getClanChannel();
			if (clan != null)
			{
				for (ClanChannelMember member : clan.getMembers())
				{
					onlineNames.add(Text.standardize(member.getName()));
				}
			}

			ClanChannel guest = client.getGuestClanChannel();
			if (guest != null)
			{
				for (ClanChannelMember member : guest.getMembers())
				{
					onlineNames.add(Text.standardize(member.getName()));
				}
			}

			FriendsChatManager friendsChat = client.getFriendsChatManager();
			if (friendsChat != null)
			{
				for (FriendsChatMember member : friendsChat.getMembers())
				{
					onlineNames.add(Text.standardize(member.getName()));
				}
			}

			Map<Integer, Integer> onlineByTeam = new HashMap<>();
			for (Map.Entry<String, Integer> entry : playerTeams.entrySet())
			{
				if (onlineNames.contains(entry.getKey()))
				{
					onlineByTeam.merge(entry.getValue(), 1, Integer::sum);
				}
			}

			SwingUtilities.invokeLater(() -> consumer.accept(onlineByTeam));
		});
	}

	/**
	 * Appends the team badge to names while the client lays out friends list
	 * rows, using the same script callbacks as the core Friend Notes plugin.
	 */
	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!config.friendsListIcons())
		{
			return;
		}

		switch (event.getEventName())
		{
			case "friendsChatSetText":
			{
				Object[] objectStack = client.getObjectStack();
				int objectStackSize = client.getObjectStackSize();
				String rsn = (String) objectStack[objectStackSize - 1];
				Integer team = playerTeams.get(Text.standardize(rsn));
				currentlyLayoutingTeam = null;
				if (team != null)
				{
					int iconIndex = chatIconManager.chatIconIndex(iconIds[team - 1]);
					if (iconIndex != -1)
					{
						currentlyLayoutingTeam = team;
						objectStack[objectStackSize - 1] = rsn + " <img=" + iconIndex + ">";
					}
				}
				break;
			}
			case "friendsChatSetPosition":
			{
				if (currentlyLayoutingTeam == null)
				{
					return;
				}

				int[] intStack = client.getIntStack();
				int intStackSize = client.getIntStackSize();
				intStack[intStackSize - 4] += TeamIconFactory.BADGE_SIZE + 1;
				break;
			}
		}
	}

	/**
	 * Appends the team badge to names in the clan and guest clan member lists
	 * after the client rebuilds them.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.CLAN_SIDEPANEL_DRAW || !config.clanListIcons())
		{
			return;
		}

		tagMemberList(InterfaceID.ClansSidepanel.PLAYERLIST);
		tagMemberList(InterfaceID.ClansGuestSidepanel.PLAYERLIST);
	}

	private void tagMemberList(int componentId)
	{
		Widget list = client.getWidget(componentId);
		if (list == null || list.getChildren() == null)
		{
			return;
		}

		for (Widget child : list.getChildren())
		{
			if (child == null)
			{
				continue;
			}

			String text = child.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}

			// strip any tag we added on a previous pass: CLAN_SIDEPANEL_DRAW fires
			// per panel but we tag both, so the non-rebuilt panel keeps our tag
			String stripped = stripOwnListTags(text);

			// non-name children (e.g. world numbers) simply won't match the roster
			String newText = stripped;
			Integer team = playerTeams.get(Text.standardize(stripped));
			if (team != null)
			{
				int iconIndex = chatIconManager.chatIconIndex(iconIds[team - 1]);
				if (iconIndex != -1)
				{
					newText = stripped + " <img=" + iconIndex + ">";
				}
			}

			if (!newText.equals(text))
			{
				child.setText(newText);
			}
		}
	}

	/**
	 * Removes this plugin's img tags including the space we prepend to them in
	 * widget list entries.
	 */
	private String stripOwnListTags(String text)
	{
		for (int id : iconIds)
		{
			int iconIndex = chatIconManager.chatIconIndex(id);
			if (iconIndex != -1)
			{
				text = text.replace(" <img=" + iconIndex + ">", "");
			}
		}
		return text;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (PLAYER_CHAT_TYPES.contains(event.getType()))
		{
			tagMessageNode(event.getMessageNode());
		}
		else if (BROADCAST_TYPES.contains(event.getType()))
		{
			tagBroadcastNode(event.getMessageNode());
		}
	}

	/**
	 * The configured color for a team, falling back to the default palette.
	 */
	Color teamColor(int team)
	{
		String stored = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamColorKey(team));
		if (stored != null && !stored.isEmpty())
		{
			try
			{
				return Color.decode(stored);
			}
			catch (NumberFormatException ex)
			{
				log.debug("invalid stored color for team {}: {}", team, stored);
			}
		}
		return TeamIconFactory.defaultTeamColor(team);
	}

	private void updateIconImages()
	{
		for (int team = 1; team <= MAX_TEAMS; team++)
		{
			BufferedImage badge = TeamIconFactory.createBadge(teamColor(team));
			badgeImages[team - 1] = badge;
			chatIconManager.updateChatIcon(iconIds[team - 1], badge);
		}
	}

	/**
	 * Re-runs the friends list build script so name tags reflect the current
	 * roster (mirrors the core Friend Notes plugin).
	 */
	private void rebuildFriendsList()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			client.runScript(
				ScriptID.FRIENDS_UPDATE,
				InterfaceID.Friends.LIST_CONTAINER,
				InterfaceID.Friends.SORT_NAME,
				InterfaceID.Friends.SORT_RECENT,
				InterfaceID.Friends.SORT_WORLD,
				InterfaceID.Friends.SORT_LEGACY,
				InterfaceID.Friends.LIST,
				InterfaceID.Friends.SCROLLBAR,
				InterfaceID.Friends.LOADING,
				InterfaceID.Friends.TOOLTIP
			);
		});
	}

	/**
	 * Re-runs the clan sidepanel draw scripts so member list tags reflect the
	 * current roster (same redraw trick as the core Chat Channel plugin).
	 */
	private void rebuildClanLists()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			Widget w = client.getWidget(InterfaceID.ClansSidepanel.UNIVERSE);
			if (w != null)
			{
				client.runScript(w.getOnVarTransmitListener());
			}

			w = client.getWidget(InterfaceID.ClansGuestSidepanel.UNIVERSE);
			if (w != null)
			{
				client.runScript(w.getOnVarTransmitListener());
			}
		});
	}

	boolean hasRoster()
	{
		return !playerTeams.isEmpty();
	}

	/**
	 * The team for an already-standardized player name, or null.
	 */
	Integer teamFor(String standardizedName)
	{
		return playerTeams.get(standardizedName);
	}

	BufferedImage badgeImage(int team)
	{
		return team >= 1 && team <= MAX_TEAMS ? badgeImages[team - 1] : null;
	}

	/**
	 * Adds, updates, or removes our badge on a message node's sender name to
	 * match the current roster. Safe to call repeatedly on the same node.
	 */
	private void tagMessageNode(MessageNode node)
	{
		String name = node.getName();
		if (name == null || name.isEmpty())
		{
			return;
		}

		String strippedName = stripOwnTags(name);
		Integer team = playerTeams.get(Text.standardize(strippedName));
		String tag = "";
		if (team != null)
		{
			int iconIndex = chatIconManager.chatIconIndex(iconIds[team - 1]);
			if (iconIndex != -1)
			{
				tag = "<img=" + iconIndex + ">";
			}
		}

		String newName = tag + strippedName;
		if (!newName.equals(name))
		{
			node.setName(newName);
		}
	}

	/**
	 * Adds, updates, or removes our badge before the player name inside a clan
	 * broadcast message (collection log / drop announcements), where the name
	 * is part of the message text rather than the sender field.
	 */
	private void tagBroadcastNode(MessageNode node)
	{
		String value = node.getValue();
		if (value == null || value.isEmpty())
		{
			return;
		}

		String stripped = stripOwnTags(value);
		String newValue = stripped;

		if (config.broadcastIcons())
		{
			Matcher matcher = BROADCAST_PATTERN.matcher(Text.removeTags(stripped));
			if (matcher.find())
			{
				String playerName = matcher.group(1);
				Integer team = playerTeams.get(Text.standardize(playerName));
				if (team != null)
				{
					int iconIndex = chatIconManager.chatIconIndex(iconIds[team - 1]);
					if (iconIndex != -1)
					{
						String tag = "<img=" + iconIndex + ">";
						int at = stripped.indexOf(playerName);
						newValue = at >= 0
							? stripped.substring(0, at) + tag + stripped.substring(at)
							: tag + stripped;
					}
				}
			}
		}

		if (!newValue.equals(value))
		{
			node.setValue(newValue);
		}
	}

	/**
	 * Removes any of this plugin's img tags from a name, leaving other tags
	 * (e.g. friends chat rank icons) intact.
	 */
	private String stripOwnTags(String name)
	{
		for (int id : iconIds)
		{
			int iconIndex = chatIconManager.chatIconIndex(id);
			if (iconIndex != -1)
			{
				name = name.replace("<img=" + iconIndex + ">", "");
			}
		}
		return name;
	}

	/**
	 * Re-applies tagging to all buffered chat lines so roster changes update
	 * messages already on screen. Must run on the client thread.
	 */
	private void retagChatHistory()
	{
		Map<Integer, ChatLineBuffer> chatLineMap = client.getChatLineMap();
		if (chatLineMap == null)
		{
			return;
		}

		boolean removeAll = navButton == null; // shutting down
		for (ChatLineBuffer buffer : chatLineMap.values())
		{
			if (buffer == null)
			{
				continue;
			}

			for (MessageNode node : buffer.getLines())
			{
				if (node == null)
				{
					continue;
				}

				if (PLAYER_CHAT_TYPES.contains(node.getType()))
				{
					if (removeAll)
					{
						String name = node.getName();
						if (name != null && !name.isEmpty())
						{
							String stripped = stripOwnTags(name);
							if (!stripped.equals(name))
							{
								node.setName(stripped);
							}
						}
					}
					else
					{
						tagMessageNode(node);
					}
				}
				else if (BROADCAST_TYPES.contains(node.getType()))
				{
					if (removeAll)
					{
						String value = node.getValue();
						if (value != null && !value.isEmpty())
						{
							String stripped = stripOwnTags(value);
							if (!stripped.equals(value))
							{
								node.setValue(stripped);
							}
						}
					}
					else
					{
						tagBroadcastNode(node);
					}
				}
			}
		}

		client.refreshChat();
	}

	private void rebuildPlayerTeams()
	{
		playerTeams.clear();
		int teamCount = Math.min(Math.max(config.teamCount(), 1), MAX_TEAMS);
		for (int team = 1; team <= teamCount; team++)
		{
			String names = configManager.getConfiguration(BingoTeamIconsConfig.GROUP, BingoTeamIconsPanel.teamNamesKey(team));
			if (names == null || names.isEmpty())
			{
				continue;
			}

			for (String name : names.split("[,\n]"))
			{
				String standardized = Text.standardize(name);
				if (!standardized.isEmpty())
				{
					playerTeams.putIfAbsent(standardized, team);
				}
			}
		}
	}
}

package com.bingoteamicons;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.TreeSet;
import java.util.regex.Pattern;
import java.util.zip.DataFormatException;
import java.util.zip.Deflater;
import java.util.zip.Inflater;
import net.runelite.client.util.Text;

/**
 * Encodes and decodes the shareable roster code.
 *
 * <p>Wire format is {@code BTI1:} followed by Base64 of DEFLATE-compressed JSON.
 *
 * <p>Real player names are close to random over a 39-character alphabet, so there
 * is very little redundancy to remove: measured against 700 live hiscore names, a
 * roster of that size encodes to roughly 5,000 characters however it is packed,
 * which is why sharing also supports a file. Sorting each list is the one cheap
 * win, and DEFLATE is already within a few percent of the entropy floor.
 */
class BingoTeamIconsSyncCodec
{
	static final String PREFIX = "BTI1:";

	/** Codes come from strangers, so cap what we will inflate. */
	private static final int MAX_INFLATED_BYTES = 512 * 1024;
	private static final int MAX_CODE_CHARS = 1024 * 1024;
	private static final int MAX_MEMBERS = 20_000;
	static final int MAX_LABEL_CHARS = 24;

	// Rosters are persisted as a [,\n] separated blob, so a name containing either
	// would silently split into two entries on the next read. Restricting to the
	// real RSN character set keeps decode idempotent with rebuildPlayerTeams.
	private static final int MAX_NAME_CHARS = 12;
	private static final Pattern VALID_NAME = Pattern.compile("[a-z0-9 _-]{1," + MAX_NAME_CHARS + "}");

	// Outside the name charset, and not escaped by Gson. A newline separator would
	// be written as "\n", costing a character per name.
	private static final char MEMBER_SEPARATOR = '|';

	private final Gson gson;

	BingoTeamIconsSyncCodec(Gson gson)
	{
		this.gson = gson;
	}

	static class SyncTeam
	{
		String name;
		String color;
		/** Front-coded, newline separated. Use {@link #memberList()} to read. */
		String members;

		List<String> memberList()
		{
			return decodeMembers(members);
		}
	}

	static class SyncPayload
	{
		String label;
		List<SyncTeam> teams;
	}

	static class SyncCodeException extends Exception
	{
		SyncCodeException(String message)
		{
			super(message);
		}
	}

	String encode(SyncPayload payload)
	{
		byte[] json = gson.toJson(payload).getBytes(StandardCharsets.UTF_8);
		return PREFIX + Base64.getEncoder().encodeToString(deflate(json));
	}

	SyncPayload decode(String code) throws SyncCodeException
	{
		if (code == null || code.trim().isEmpty())
		{
			throw new SyncCodeException("No code entered.");
		}

		if (code.length() > MAX_CODE_CHARS)
		{
			throw new SyncCodeException("That code is too large to be a team list.");
		}

		// pasted codes routinely arrive wrapped across lines
		String compact = code.replaceAll("\\s+", "");

		if (!compact.startsWith(PREFIX))
		{
			if (compact.matches("(?i)^BTI\\d+:.*"))
			{
				throw new SyncCodeException(
					"That code was made by a newer version of the plugin. Update Bingo Team Icons and try again.");
			}
			throw new SyncCodeException("That doesn't look like a team code. It should start with " + PREFIX);
		}

		byte[] compressed;
		try
		{
			compressed = Base64.getDecoder().decode(compact.substring(PREFIX.length()));
		}
		catch (IllegalArgumentException ex)
		{
			throw new SyncCodeException("The code is damaged. Copy it again, making sure you get all of it.");
		}

		byte[] json;
		try
		{
			json = inflate(compressed);
		}
		catch (DataFormatException ex)
		{
			throw new SyncCodeException("The code is damaged or incomplete. Copy it again, making sure you get all of it.");
		}

		SyncPayload payload;
		try
		{
			payload = gson.fromJson(new String(json, StandardCharsets.UTF_8), SyncPayload.class);
		}
		catch (JsonParseException ex)
		{
			throw new SyncCodeException("The code is damaged and could not be read.");
		}

		if (payload == null || payload.teams == null || payload.teams.isEmpty())
		{
			throw new SyncCodeException("That code contains no teams.");
		}

		if (payload.teams.size() > BingoTeamIconsPlugin.MAX_TEAMS)
		{
			throw new SyncCodeException("That code contains " + payload.teams.size()
				+ " teams, but only " + BingoTeamIconsPlugin.MAX_TEAMS + " are supported.");
		}

		payload.label = sanitizeLabel(payload.label);

		int total = 0;
		for (SyncTeam team : payload.teams)
		{
			if (team == null)
			{
				throw new SyncCodeException("The code is damaged and could not be read.");
			}

			team.name = sanitizeLabel(team.name);
			total += team.memberList().size();
			if (total > MAX_MEMBERS)
			{
				throw new SyncCodeException("That code contains too many players.");
			}
		}

		return payload;
	}

	/**
	 * Trims a user-supplied label and strips anything that could be read as a
	 * formatting tag once it reaches a Swing label or a config value.
	 */
	static String sanitizeLabel(String label)
	{
		if (label == null)
		{
			return "";
		}

		String clean = Text.removeTags(label).replaceAll("[\\p{Cntrl}]", " ").trim();
		return clean.length() > MAX_LABEL_CHARS ? clean.substring(0, MAX_LABEL_CHARS).trim() : clean;
	}

	/**
	 * Standardizes, de-duplicates and sorts names into a separated list.
	 *
	 * <p>Sorting is mostly for the reader: an imported roster shows up alphabetised
	 * in the panel rather than in whatever order the organiser happened to paste.
	 * It also groups shared prefixes where DEFLATE can reach them, but that was
	 * measured at only ~1.6% on real player names — worth having, not worth
	 * building on. Eliding those prefixes by hand was tried and is a net loss: it
	 * costs a byte per name and breaks up the repetition LZ77 feeds on.
	 */
	static String encodeMembers(Iterable<String> names)
	{
		TreeSet<String> sorted = new TreeSet<>();
		for (String name : names)
		{
			String standardized = Text.standardize(name);
			if (VALID_NAME.matcher(standardized).matches())
			{
				sorted.add(standardized);
			}
		}
		return String.join(String.valueOf(MEMBER_SEPARATOR), sorted);
	}

	static List<String> decodeMembers(String encoded)
	{
		List<String> names = new ArrayList<>();
		if (encoded == null || encoded.isEmpty())
		{
			return names;
		}

		for (String entry : encoded.split("\\" + MEMBER_SEPARATOR, -1))
		{
			String name = Text.standardize(entry);
			if (VALID_NAME.matcher(name).matches())
			{
				names.add(name);
			}
		}
		return names;
	}

	private static byte[] deflate(byte[] input)
	{
		Deflater deflater = new Deflater(Deflater.BEST_COMPRESSION);
		try
		{
			deflater.setInput(input);
			deflater.finish();

			ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(64, input.length / 3));
			byte[] buffer = new byte[8192];
			while (!deflater.finished())
			{
				out.write(buffer, 0, deflater.deflate(buffer));
			}
			return out.toByteArray();
		}
		finally
		{
			deflater.end();
		}
	}

	private static byte[] inflate(byte[] input) throws DataFormatException
	{
		Inflater inflater = new Inflater();
		try
		{
			inflater.setInput(input);

			ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(64, input.length * 3));
			byte[] buffer = new byte[8192];
			while (!inflater.finished())
			{
				int read = inflater.inflate(buffer);
				if (read == 0 && (inflater.needsInput() || inflater.needsDictionary()))
				{
					throw new DataFormatException("truncated stream");
				}

				if (out.size() + read > MAX_INFLATED_BYTES)
				{
					throw new DataFormatException("inflated output exceeds cap");
				}
				out.write(buffer, 0, read);
			}
			return out.toByteArray();
		}
		finally
		{
			inflater.end();
		}
	}
}

package com.bingoteamicons;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;

/**
 * Draws the team badge above rostered players' heads, at the spot a rank icon
 * would occupy next to the overhead name (mirrors PlayerIndicatorsOverlay).
 */
class BingoTeamIconsOverlay extends Overlay
{
	private static final int ACTOR_OVERHEAD_TEXT_MARGIN = 40;

	private final Client client;
	private final BingoTeamIconsPlugin plugin;
	private final BingoTeamIconsConfig config;

	@Inject
	private BingoTeamIconsOverlay(Client client, BingoTeamIconsPlugin plugin, BingoTeamIconsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_MED);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.nameplateIcons() || !plugin.hasRoster())
		{
			return null;
		}

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return null;
		}

		FontMetrics fm = graphics.getFontMetrics();
		Player localPlayer = client.getLocalPlayer();
		for (Player player : wv.players())
		{
			if (player == localPlayer)
			{
				continue;
			}

			String name = player.getName();
			if (name == null || !wv.contains(player.getLocalLocation()))
			{
				continue;
			}

			Integer team = plugin.teamFor(Text.standardize(name));
			if (team == null)
			{
				continue;
			}

			BufferedImage badge = plugin.badgeImage(team);
			if (badge == null)
			{
				continue;
			}

			Point textLocation = player.getCanvasTextLocation(graphics, name, player.getLogicalHeight() + ACTOR_OVERHEAD_TEXT_MARGIN);
			if (textLocation == null)
			{
				continue;
			}

			Point imageLocation = new Point(
				textLocation.getX() - badge.getWidth() - 5,
				textLocation.getY() - fm.getHeight() / 2 - badge.getHeight() / 2 + 2);
			OverlayUtil.renderImageLocation(graphics, imageLocation, badge);
		}

		return null;
	}
}

